CREATE TABLE abbreviation_state (id INTEGER PRIMARY KEY CHECK (id=1), revision BIGINT NOT NULL DEFAULT 0, dataset_key VARCHAR(36) NOT NULL);
CREATE TABLE abbreviation (code VARCHAR(16) PRIMARY KEY, meaning VARCHAR(80) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE abbreviation_alias (normalized VARCHAR(320) PRIMARY KEY, code VARCHAR(16) NOT NULL REFERENCES abbreviation(code), expression VARCHAR(80) NOT NULL, kind VARCHAR(10) NOT NULL CHECK (kind IN ('CODE','MEANING','VARIANT')));
CREATE INDEX abbreviation_alias_code ON abbreviation_alias(code);
